def bellman_ford(n, edges, s):
  dis[s]=0; 其余 INF
  for i in range(n):
    updated = False
    for (u,v,w) in edges:
      if dis[u]!=INF and dis[u]+w < dis[v]:
        dis[v] = dis[u]+w; updated=True
    if not updated: break
  # 第 n 轮检测负环
  for (u,v,w) in edges:
    if dis[u]!=INF and dis[u]+w < dis[v]:
      return 's 可达负环'
  return dis
